    private static void SendStreamKey(ushort key,bool down){if(key is 1 or 2){var mouse=new StreamMouseInput{Flags=key==1?(down?2u:4u):(down?8u:16u)};if(SendMouseInput(1,new[]{mouse},40)!=1)throw new Exception("游戏未接受鼠标按键");Interlocked.Increment(ref streamNativeMouseButtons);return;}var scan=MapStreamVirtualKey(key,0);if(scan==0)throw new Exception("按键映射无效");var input=new StreamKeyInput{Type=1,Scan=(ushort)scan,Flags=8u|(down?0u:2u)|(key is >=37 and <=40?1u:0u)};if(SendInput(1,new[]{input},40)!=1)throw new Exception("游戏未接受按键输入，请检查游戏与插件权限");Interlocked.Increment(ref streamNativeKeyEvents);}
    private void ReleaseStreamKeys(){foreach(var key in streamHeldKeys.ToArray()){try{if(key!=1||!streamPointerDown)streamKeyWriter(key,false);}catch{}streamHeldKeys.Remove(key);}streamKeyTouched=0;}
    private object ApplyStreamKeys(JsonElement root,string auth){string nonce=root.GetProperty("session").GetString()??"";long sequence=root.GetProperty("sequence").GetInt64();var requested=root.GetProperty("keys").EnumerateArray().Select(e=>e.GetString()??"").ToArray();if(requested.Length>8||requested.Any(k=>!StreamKeys.ContainsKey(k))||sequence<1)throw new Exception("串流按键请求无效");var wanted=requested.Select(k=>StreamKeys[k]).ToHashSet();lock(streamGate){if(!Equal(auth,streamOwner)||streamProcess==null||streamWindow==0||nonce.Length==0||!Equal(nonce,streamInputSession))throw new Exception("串流控制会话已失效");if(!root.TryGetProperty("control",out var epoch)||epoch.GetInt64()!=streamControlSequence)throw new Exception("控制模式已切换，旧指令已丢弃");if(sequence<=streamKeySequence)return new{ok=true,ignored=true};streamKeySequence=sequence;if(wanted.Count>0&&!streamControlEnabled)throw new Exception("游戏控制暂未就绪，请稍后重试");if(wanted.Count>0&&streamFocusProbe()!=streamWindow){ReleaseStreamKeys();throw new Exception("请先让游戏窗口处于电脑前台");}long up=root.TryGetProperty("wheelUp",out var wu)?wu.GetInt64():streamWheelUp,down=root.TryGetProperty("wheelDown",out var wd)?wd.GetInt64():streamWheelDown;if(up<streamWheelUp||down<streamWheelDown||up-streamWheelUp>20||down-streamWheelDown>20)throw new Exception("滚轮状态无效");if((up!=streamWheelUp||down!=streamWheelDown)&&(!streamControlEnabled||streamFocusProbe()!=streamWindow))throw new Exception("请先启用前台游戏控制");int ticks=(int)((up-streamWheelUp)-(down-streamWheelDown));if(ticks!=0)streamWheelWriter(ticks);streamWheelUp=up;streamWheelDown=down;foreach(var key in streamHeldKeys.Except(wanted).ToArray()){if(key!=1||!streamPointerDown)streamKeyWriter(key,false);streamHeldKeys.Remove(key);}try{foreach(var key in wanted.Except(streamHeldKeys)){if(key!=1||!streamPointerDown)streamKeyWriter(key,true);streamHeldKeys.Add(key);}}catch{ReleaseStreamKeys();throw;}streamKeyTouched=Environment.TickCount64;return new{ok=true};}}
    private void CheckStreamKeys(){string owner;lock(streamGate)owner=streamOwner;bool authorized=owner.Length>0&&Authorized(owner);lock(streamGate){if(owner!=streamOwner)return;if(!authorized||streamWindow==0||streamFocusProbe()!=streamWindow){ReleaseStreamKeys();ReleaseStreamPointer();streamControlEnabled=false;}else{if((streamHeldKeys.Count>0&&Environment.TickCount64-streamKeyTouched>500)||(streamPointerDown&&Environment.TickCount64-streamPointerTouched>500)){ReleaseStreamKeys();ReleaseStreamPointer();streamControlEnabled=false;}}}}
    private long streamTextSequence;private Action<string> streamTextWriter=WriteStreamText;
    private static void WriteStreamText(string text){var input=new StreamKeyInput[text.Length*2];for(int i=0;i<text.Length;i++){input[i*2]=new StreamKeyInput{Type=1,Scan=text[i],Flags=4};input[i*2+1]=new StreamKeyInput{Type=1,Scan=text[i],Flags=6};}if(SendInput((uint)input.Length,input,40)!=(uint)input.Length)throw new Exception("游戏未接受完整文字输入，请检查游戏输入框");Interlocked.Add(ref streamNativeKeyEvents,input.Length);}
    private object ApplyStreamIme(JsonElement root,string auth){string session=root.GetProperty("session").GetString()??"",text=root.GetProperty("text").GetString()??"";int deletes=root.GetProperty("delete").GetInt32();long sequence=root.GetProperty("sequence").GetInt64();if(sequence<1||text.Length>500||text.Any(char.IsControl)||deletes<0||deletes>100||(deletes==0&&text.Length==0)||(deletes>0&&text.Length>0))throw new Exception("输入法数据无效");lock(streamGate){if(!Equal(auth,streamOwner)||streamProcess==null||string.IsNullOrEmpty(session)||!Equal(session,streamInputSession))throw new Exception("串流输入会话已失效");if(sequence<=streamTextSequence)return new{ok=true,ignored=true};if(streamFocusProbe()!=streamWindow)throw new Exception("请先点选游戏输入框");ReleaseStreamKeys();ReleaseStreamPointer();streamTextSequence=sequence;if(deletes>0){for(int i=0;i<deletes;i++){streamKeyWriter(8,true);streamKeyWriter(8,false);}}else streamTextWriter(text);return new{ok=true};}}
    private object ApplyStreamText(JsonElement root,string auth){string nonce=root.GetProperty("session").GetString()??"",text=root.GetProperty("text").GetString()??"";long sequence=root.GetProperty("sequence").GetInt64();if(sequence<1||text.Length<1||text.Length>500||text.Any(char.IsControl))throw new Exception("请输入1至500字的单行文字");lock(streamGate){if(!Equal(auth,streamOwner)||streamProcess==null||!Equal(nonce,streamInputSession)||nonce.Length==0)throw new Exception("串流输入会话已失效");if(sequence<=streamTextSequence)return new{ok=true,ignored=true};if(streamFocusProbe()!=streamWindow)throw new Exception("请先让游戏窗口位于前台并点选游戏输入框");ReleaseStreamKeys();ReleaseStreamPointer();streamTextSequence=sequence;streamTextWriter(text);return new{ok=true};}}
    private long streamWheelUp,streamWheelDown;private Action<int> streamWheelWriter=SendStreamWheel;private static void SendStreamWheel(int ticks){var input=new StreamMouseInput{Flags=0x800,MouseData=unchecked((uint)(ticks*120))};if(SendMouseInput(1,new[]{input},40)!=1)throw new Exception("游戏未接受滚轮输入");Interlocked.Increment(ref streamNativeMouseButtons);}
