    private static void MoveStreamPointer(nint window,float x,float y){if(!GetClientRect(window,out var rect))throw new Exception("游戏窗口尺寸不可用");var point=new StreamPoint{X=(int)Math.Round(x*Math.Max(0,rect.Right-1)),Y=(int)Math.Round(y*Math.Max(0,rect.Bottom-1))};if(!ClientToScreen(window,ref point))throw new Exception("游戏窗口位置不可用");int left=GetSystemMetrics(76),top=GetSystemMetrics(77),width=GetSystemMetrics(78),height=GetSystemMetrics(79);if(width<2||height<2)throw new Exception("屏幕尺寸不可用");var input=new StreamMouseInput{X=(int)Math.Round((point.X-left)*65535d/(width-1)),Y=(int)Math.Round((point.Y-top)*65535d/(height-1)),Flags=0xC001u};if(SendMouseInput(1,new[]{input},40)!=1)throw new Exception("游戏未接受鼠标输入");Interlocked.Increment(ref streamNativeMouseMoves);}
    private static void MoveStreamRelative(nint window,float x,float y){if(!GetClientRect(window,out var rect)||rect.Right<2||rect.Bottom<2)throw new Exception("游戏窗口尺寸不可用");if(!GetCursorPos(out var point)||!ScreenToClient(window,ref point))throw new Exception("鼠标位置不可用");float nx=Math.Clamp((point.X+x*rect.Right)/(rect.Right-1f),0f,1f),ny=Math.Clamp((point.Y+y*rect.Bottom)/(rect.Bottom-1f),0f,1f);MoveStreamPointer(window,nx,ny);}
    private static void WriteStreamPointerButton(bool down){var input=new StreamMouseInput{Flags=down?2u:4u};if(SendMouseInput(1,new[]{input},40)!=1)throw new Exception("游戏未接受鼠标按键输入");Interlocked.Increment(ref streamNativeMouseButtons);}
    private static void WriteStreamPointer(nint window,float x,float y,bool down){if(down)MoveStreamPointer(window,x,y);WriteStreamPointerButton(down);}
    private void ReleaseStreamPointer(){if(streamPointerDown){try{if(!streamHeldKeys.Contains(1))streamPointerWriter(streamWindow,streamPointerX,streamPointerY,false);}catch{}streamPointerDown=false;}streamPointerTouched=0;}
    private object ApplyStreamPointer(JsonElement root,string auth){string session=root.GetProperty("session").GetString()??"";long sequence=root.GetProperty("sequence").GetInt64();float x=root.GetProperty("x").GetSingle(),y=root.GetProperty("y").GetSingle();bool down=root.GetProperty("down").GetBoolean();bool relative=root.TryGetProperty("relative",out var relativeValue)&&relativeValue.GetBoolean(),begin=root.TryGetProperty("begin",out var beginValue)&&beginValue.GetBoolean();if(sequence<1||!float.IsFinite(x)||!float.IsFinite(y)||(relative?(Math.Abs(x)>10000||Math.Abs(y)>10000):(x<0||x>1||y<0||y>1)))throw new Exception("鼠标输入无效");lock(streamGate){if(!Equal(auth,streamOwner)||streamProcess==null||streamWindow==0||session.Length==0||!Equal(session,streamInputSession))throw new Exception("串流控制会话已失效");if(!root.TryGetProperty("control",out var epoch)||epoch.GetInt64()!=streamControlSequence)throw new Exception("控制模式已切换，旧指令已丢弃");if(sequence<=streamPointerSequence)return new{ok=true,ignored=true};if(!streamControlEnabled)throw new Exception("游戏控制暂未就绪，请稍后重试");if(streamFocusProbe()!=streamWindow){ReleaseStreamPointer();throw new Exception("请先让游戏窗口处于电脑前台");}if(relative){if(begin)streamRelativeMover(streamWindow,0,0);else if(x!=streamPointerX||y!=streamPointerY)streamRelativeMover(streamWindow,x-streamPointerX,y-streamPointerY);if(down!=streamPointerDown&&!streamHeldKeys.Contains(1))streamPointerButtonWriter(down);}else{if(down!=streamPointerDown&&!streamHeldKeys.Contains(1))streamPointerWriter(streamWindow,x,y,down);else if(x!=streamPointerX||y!=streamPointerY)streamPointerMover?.Invoke(streamWindow,x,y);}streamPointerSequence=sequence;streamPointerX=x;streamPointerY=y;streamPointerDown=down;streamPointerTouched=Environment.TickCount64;return new{ok=true};}}
